using System;using System.IO;using Ashfall.Modules.Sessions;using Ashfall.Integration.Playable.Match;using Ashfall.Integration.Playable.MatchZone;using Ashfall.Integration.Playable.Networking;
partial class LobbyCases
{
 static void SkewTick(Pair pair){pair.Now+=.05;pair.Host.Tick(pair.Now);pair.Client.Tick(pair.Now+1000);}
 static void RoundCases()
 {
  foreach(string preset in new[]{"team_revive","team_respawn","free_for_all"}){
   var source=R24PlayableMatchRules.ForPreset(preset,"range");using(var stream=new MemoryStream()){using(var writer=new BinaryWriter(stream,System.Text.Encoding.UTF8,true))R24LanRoundCodec.Write(writer,source);Need(stream.Length<280,"Compact source rule snapshot fits bounded map frame");stream.Position=0;var read=R24LanRoundCodec.Read(new BinaryReader(stream),"range");foreach(string key in R24PlayableMatchRules.SourceKeys)Need(Object.Equals(source.ReadSourceValue(key),read.ReadSourceValue(key)),"Every actual source rule roundtrips: "+preset+"/"+key);Need(stream.Position==stream.Length,"No unread rule bytes");}
  }
  var clock=new R24LanHostClock();Need(clock.Reply(1000,.05,1000.1)&&Math.Abs(clock.Now(1000.2)-.2)<1e-8,"NTP-style midpoint removes1000s peer clock offset");Need(!clock.Reply(12,12,11)&&!clock.Reply(1,Double.NaN,2),"Invalid or backward clock samples refused");Need(clock.Reply(1012,12.1,1012.2),"Rolling RTT sample permits route-latency change after10s");
  var a=new R24LanRoundRandom(9183);var b=new R24LanRoundRandom(9183);for(int i=0;i<8;i++){double x=a.Next();Need(x==b.Next()&&x>=0&&x<1,"Source zone RNG contract, same host seed");}
  var local=new R24LocalMatchClock();local.Begin(60,2);local.BindNetworkRound(2,12);local.Synchronize(10);Need(local.Round==2&&local.Elapsed==12,"Host round index bound; clock corrections do not roll back Health time");
  using(var pair=new Pair()){
   for(int i=0;i<5;i++)pair.Tick();var rules=R24PlayableMatchRules.ForPreset("free_for_all","range").With("time_limit",60).With("rounds",2).With("zone_wait",0);string hash=new string('c',64);
   Need(!pair.Client.BeginRoundSelection(rules,hash,1234),"Client cannot author shared start");Need(pair.Host.BeginRoundSelection(rules,hash,1234)&&pair.Host.ReportMapLoaded(hash),"Actual host round begin enters existing readiness lifecycle");for(int i=0;i<6;i++)SkewTick(pair);Need(pair.Client.SelectedMap.Rules!=null&&pair.Client.SelectedMap.Seed==1234,"Host rules/seed reach offset-clock client");Need(pair.Client.ReportMapLoaded(hash),"Real member acknowledges round world");for(int i=0;i<6;i++)SkewTick(pair);
   Need(pair.Host.MapStage==SessionStage.Match&&pair.Client.MapStage==SessionStage.Match&&Loaded(pair.Host)==2&&pair.Host.RoundCountdown>2.5,"Real Session Match activates behind loaded barrier and3s countdown");Need(pair.Client.ClockSynchronized,"Offset client clock synchronized over actual protocol frames");
   pair.Now=pair.Host.SelectedMap.StartsAt+2;pair.Host.Tick(pair.Now);pair.Client.Tick(pair.Now+1000);for(int i=0;i<3;i++)SkewTick(pair);Need(pair.Host.RoundCountdown==0&&pair.Client.RoundCountdown==0&&Math.Abs(pair.Host.RoundElapsed-pair.Client.RoundElapsed)<.06,"Host/client shared elapsed remains aligned despite1000s offset");
   var rng1=new R24LanRoundRandom(pair.Host.SelectedMap.Seed);var rng2=new R24LanRoundRandom(pair.Client.SelectedMap.Seed);var zr=new R24ZoneRules(true,rules.ZoneDamage,rules.ZoneSpeed,rules.ZoneWait);var zone1=new R24MatchZoneHost(zr,-50,-50,50,50,0,rng1.Next);var zone2=new R24MatchZoneHost(zr,-50,-50,50,50,0,rng2.Next);zone1.Tick(23,.1,true);zone2.Tick(23,.1,true);Need(zone1.State.Next.X==zone2.State.Next.X&&zone1.State.Next.Z==zone2.State.Next.Z&&zone1.State.Ends==zone2.State.Ends,"Same authoritative seed/time gives same actual source zone plan");
   pair.Now=pair.Host.SelectedMap.StartsAt+60.1;pair.Host.Tick(pair.Now);pair.Client.Tick(pair.Now+1000);for(int i=0;i<3;i++)SkewTick(pair);Need(pair.Host.Epoch==2&&pair.Host.SelectedMap.Round==2&&pair.Host.MapStage==SessionStage.Loading&&Loaded(pair.Host)==0,"Only host ends timed round and starts next real epoch/readiness barrier");Need(pair.Client.SelectedMap.Round==2&&pair.Client.SelectedMap.Seed==pair.Host.SelectedMap.Seed,"Next-round metadata and seed shared");Need(pair.Host.ReportMapLoaded(hash)&&pair.Client.ReportMapLoaded(hash),"New round uses new actual acknowledgements");for(int i=0;i<5;i++)SkewTick(pair);
   pair.Now=pair.Host.SelectedMap.StartsAt+60.1;pair.Host.Tick(pair.Now);pair.Client.Tick(pair.Now+1000);for(int i=0;i<3;i++)SkewTick(pair);Need(pair.Host.MapStage==SessionStage.Results&&pair.Client.MapStage==SessionStage.Results&&pair.Host.SelectedMap.Results&&pair.Client.SelectedMap.Results,"Final host results reaches client, no independent next-round loop");
  }
 }
}
